export type Expr = {
  readonly $expr: 'binding';
} & BindingExpr | {
  readonly $expr: 'field';
} & FieldExpr | {
  readonly $expr: 'currentItem';
} & CurrentItemExpr | {
  readonly $expr: 'parameter';
} & ParameterExpr | {
  readonly $expr: 'constant';
} & ConstantExpr | {
  readonly $expr: 'unary';
} & UnaryExpr | {
  readonly $expr: 'binary';
} & BinaryExpr | {
  readonly $expr: 'conditional';
} & ConditionalExpr | {
  readonly $expr: 'function';
} & CallExpr | {
  readonly $expr: 'typedFieldRef';
} & FieldRefExpr | {
  readonly $expr: 'literal';
} & LiteralExpr | {
  readonly $expr: 'aggregate';
} & AggregateExpr;

export interface BindingExpr {
  Binding: ValueBindingId;
}

export interface FieldExpr {
  Path: FieldPath;
  Binding?: ValueBindingId | null;
}

export type CurrentItemExpr = Record<never, never>;

export interface ParameterExpr {
  Parameter: string;
}

export interface ConstantExpr {
  Value: unknown;
}

export interface UnaryExpr {
  Operator: UnaryOperator;
  Operand: Expr;
}

export interface BinaryExpr {
  Operator: BinaryOperator;
  Left: Expr;
  Right: Expr;
}

export interface ConditionalExpr {
  Test: Expr;
  IfTrue: Expr;
  IfFalse: Expr;
  ReturnType: TypeRef;
}

export interface CallExpr {
  Function: string;
  Arguments: Expr[];
  ReturnType: TypeRef;
}

export interface FieldRefExpr {
  Path: FieldPath;
  Type: TypeRef;
}

export interface LiteralExpr {
  Type: TypeRef;
  Value: unknown;
}

export interface AggregateExpr {
  Operator: AggregateOperator;
  Source: Expr;
  GroupBy: Expr[];
  ReturnType: TypeRef;
}

export type TypeRef = {
  readonly $type: 'named';
} & NamedTypeRef | {
  readonly $type: 'opaque';
} & OpaqueRuntimeTypeRef | {
  readonly $type: 'scalar';
} & ScalarTypeRef | {
  readonly $type: 'enum';
} & EnumTypeRef | {
  readonly $type: 'entityRef';
} & EntityReferenceTypeRef | {
  readonly $type: 'array';
} & ArrayTypeRef | {
  readonly $type: 'object';
} & ObjectTypeRef | {
  readonly $type: 'quantity';
} & QuantityTypeRef | {
  readonly $type: 'json';
} & JsonTypeRef;

export interface NamedTypeRef {
  TypeId: TypeId;
}

export interface OpaqueRuntimeTypeRef {
  RuntimeType: string;
  InferenceDiagnostic?: TypeInferenceDiagnostic | null;
}

export interface ScalarTypeRef {
  Kind: ScalarTypeKind;
  Format: PrimitiveFormat;
}

export interface EnumTypeRef {
  Name: string;
  Members: string[];
}

export interface EntityReferenceTypeRef {
  Entity: EntityTypeName;
}

export interface ArrayTypeRef {
  ElementType: TypeRef;
}

export interface ObjectTypeRef {
  Fields: ObjectFieldTypeDef[];
}

export interface QuantityTypeRef {
  Quantity: string;
  BaseKind: ScalarTypeKind;
}

export interface JsonTypeRef {
  Kind: JsonTypeKind;
}

